def closest_integer(value):
    num = float(value)
    integer_part = int(num)
    decimal_part = num - integer_part
    if decimal_part == 0.5 or decimal_part == -0.5:
        return integer_part + 1 if num > 0 else integer_part - 1
    return round(num, 0)
```

