import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = {(0, 0)}
    heap = [(-grid[0][0], 0, 0)]

    while k > 0:
        val, x, y = heapq.heappop(heap)
        if k == 1:
            return [-val] + list(sorted([grid[i][j] for i, j in visited]))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                visited.add((nx, ny))
                heapq.heappush(heap, (-grid[nx][ny], nx, ny))
        k -= 1

    return []
