        return None

    sign_product = 1
    abs_sum = 0

    for num in arr:
        if num == 0:
            sign_product = 0
            break
        elif num < 0:
            sign_product *= -1

    abs_sum = sum(abs(num) for num in arr)
    return abs_sum * sign_product
