def smallest_change(arr):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, j):
        if i >= j:
            return 0
        if arr[i] == arr[j]:
            return dp(i + 1, j - 1)
        else:
            return 1 + min(dp(i + 1, j), dp(i, j - 1))

    return dp(0, len(arr) - 1)
