def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    trib = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            trib.append(1 + i // 2)
        else:
            next_value = trib[-1] + trib[-2] + trib[i]
            trib.append(next_value)
    return trib[:n+1]
```

