def file_name_check(file_name):
    import re
    # Check for more than three digits
    if len(re.findall(r'\d', file_name)) > 3:
        return 'No'
    # Check for exactly one dot
    if file_name.count('.') != 1:
        return 'No'
    # Check for valid extension
    if not file_name.endswith(('.txt', '.exe', '.dll')):
        return 'No'
    # Check if the name starts with a letter
    if not file_name[0].isalpha():
        return 'No'
    # Check if the part before the dot is not empty
    if file_name.index('.') == 0:
        return 'No'
    return 'Yes'
