def tri(n):
    from math import floor

    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    sequence = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            next_value = 1 + i // 2
        else:
            next_value = sequence[-1] + sequence[-2] + sequence[floor(i / 2) + 1]
        sequence.append(next_value)

    return sequence
