def check_dict_case(my_dict):
    if not my_dict:
        return False

    lower = set()
    upper = set()

    for key in my_dict.keys():
        if not isinstance(key, str):
            return False
        if key.islower():
            lower.add(key)
        elif key.isupper():
            upper.add(key)
        else:
            return False

    return len(lower) == len(my_dict) or len(upper) == len(my_dict)
