def encrypt(s):
    import string

    alphabet = string.ascii_lowercase
    rotated_alphabet = alphabet[4:] + alphabet[:4]  # Rotate alphabet by 8 places

    encrypted_s = []
    for char in s.lower():
        if char in alphabet:
            index = alphabet.index(char)
            encrypted_s.append(rotated_alphabet[index])
        else:
            encrypted_s.append(char)

    return ''.join(encrypted_s)
