def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    vowel_shift = 'cdefgh'

    def swap_case(char):
        if char.islower():
            return char.upper()
        elif char.isupper():
            return char.lower()
        else:
            return char

    def replace_vowel(char):
        if char.lower() in vowels:
            index = vowels.index(char.lower())
            return vowel_shift[index]
        else:
            return char

    encoded = [replace_vowel(swap_case(char)) for char in message]
    return ''.join(encoded)
```

