def f(n):
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    def sum_to_x(x):
        return (x * (x + 1)) // 2

    def calc_value(i):
        if i % 2 == 0:
            return factorial(i)
        else:
            return sum_to_x(i)

    return [calc_value(i) for i in range(1, n + 1)]
