    from math import sqrt

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    max_prime = max(filter(is_prime, lst), default=0)
    return sum(int(digit) for digit in str(max_prime)) if max_prime else 0
