from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def get_neighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def dijkstra(start):
        queue = [(grid[start[0]][start[1]], start)]
        visited = set()
        while queue:
            value, (x, y) = heappop(queue)
            if (x, y) in visited:
                continue
            visited.add((x, y))
            if len(visited) == k:
                return [grid[i][j] for i, j in visited]
            for nx, ny in get_neighbors(x, y):
                if (nx, ny) not in visited:
                    heappush(queue, (grid[nx][ny], (nx, ny)))
        return []

    min_path = None
    for i in range(N):
        for j in range(N):
            path = dijkstra((i, j))
            if min_path is None or path < min_path:
                min_path = path

    return min_path
