    encrypted = ""
    for char in s:
        if 'a' <= char <= 'z':
            encrypted += chr((ord(char) - ord('a') + SHIFT) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            encrypted += chr((ord(char) - ord('A') + SHIFT) % 26 + ord('A'))
        else:
            encrypted += char
    return encrypted
