def solve(s):
    import string

    def reverse_case(char):
        if char in string.ascii_letters:
            return char.swapcase()
        return char

    if not any(char in string.ascii_letters for char in s):
        return s[::-1]

    return ''.join(reverse_case(char) for char in s)
```

