def check_dict_case(dict):
    if not dict:
        return False

    lower_case = set()
    upper_case = set()

    for key in dict.keys():
        if not isinstance(key, str):
            return False
        if key.islower():
            lower_case.add(key)
        elif key.isupper():
            upper_case.add(key)
        else:
            return False

    return len(lower_case) == len(dict) or len(upper_case) == len(dict)
```

