def anti_shuffle(s):
    from string import.whitespace

    def sort_word(word):
        return ''.join(sorted(word))

    result = []
    word = []
    for char in s:
        if char in whitespace:
            if word:
                result.append(sort_word(word))
                word = []
            result.append(char)
        else:
            word.append(char)
    if word:
        result.append(sort_word(word))

    return ''.join(result)
