def sort_array(arr):
    from operator import itemgetter

    def count_ones(n):
        return bin(n).count('1')

    arr_with_count = [(i, count_ones(i)) for i in arr]
    arr_with_count.sort(key=itemgetter(1, 0))

    return [i[0] for i in arr_with_count]
