from math import sqrt

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_multiply_prime(a):
    if a < 2:
        return False

    factors = []
    for i in range(2, int(sqrt(a)) + 1):
        if a % i == 0 and is_prime(i):
            while a % i == 0:
                a //= i
                factors.append(i)
    if a > 1 and is_prime(a):
        factors.append(a)

    return len(factors) == 3

# Example checks
print(is_multiply_prime(30))  # True
print(is_multiply_prime(60))  # False, 60 = 2 * 2 * 3 * 5
print(is_multiply_prime(2))   # False
```

