def tri(n):
    from math import floor

    def tribonacci(n):
        if n == 0:
            return 3
        if n % 2 == 0:
            return 1 + n / 2
        else:
            if n == 1:
                return 3
            else:
                a, b, c = 3, 2, tribonacci(n - 1) + tribonacci(n - 2) + tribonacci(n + 1)
                return c

    return [tribonacci(i) for i in range(1, n + 1)]
