from math import sqrt

def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    fib1, fib2 = 0, 1
    count = 0
    while True:
        fib1, fib2 = fib2, fib1 + fib2
        if is_prime(fib1):
            count += 1
            if count == n:
                return fib1
