def get_row(lst, x):
    coordinates = []
    for row_idx, row in enumerate(lst):
        for col_idx, val in enumerate(reversed(row)):
            if val == x:
                coordinates.append((row_idx, len(row) - 1 - col_idx))
    # Sort coordinates by row in ascending order and then by column in descending order within the same row
    coordinates.sort(key=lambda coord: (coord[0], -coord[1]))
    return coordinates
