from math import sqrt

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    if a < 2 or a >= 100:
        return False
    factors = []
    for i in [2, 3, 5, 7]:  # Check with the first four primes
        count = 0
        while a % i == 0:
            a //= i
            count += 1
        if count > 0:
            factors.append((i, count))
        if a == 1:
            break
    if a > 1:  # Check if there's an additional prime factor
        factors.append((a, 1))

    prime_factors = [i for i, count in factors]
    return len(prime_factors) == 3 and all(is_prime(pf) for pf in prime_factors)

# Test cases
print(is_multiply_prime(30))  # True
print(is_multiply_prime(60))  # True (2*2*3*5)
print(is_multiply_prime(29))  # False
print(is_multiply_prime(45))  # True (3*3*5)
