def prime_fib(n: int) -> int:
    def fib(n):
        a, b = 0, 1
        for _ in range(n):
            a, b = b, a + b
        return a

    count = 0
    i = 0
    while True:
        prime_fib_num = fib(i)
        if isprime(prime_fib_num):
            count += 1
            if count == n:
                return prime_fib_num
        i += 1
