def specialFilter(nums):
    def is_odd(n):
        return n % 2 != 0

    def has_odd_first_and_last_digits(n):
        n = abs(n)
        last_digit = n % 10
        first_digit = n
        while first_digit >= 10:
            first_digit //= 10
        return is_odd(first_digit) and is_odd(last_digit)

    count = 0
    for num in nums:
        if num > 10 and has_odd_first_and_last_digits(num):
            count += 1
    return count
```

