def count_nums(arr):
    def sum_of_digits(n):
        digits = []
        neg = n < 0
        while n:
            d = n % 10
            digits.append(d if not neg else -d)
            n //= 10
            if neg and d == 9 - (abs(d + 1) % 10):
                neg = False
        return sum(digits) if digits else 0

    return sum(1 for num in arr if sum_of_digits(num) > 0)
