        return True

    prev = lst[0]
    duplicates = 0

    for i in range(1, len(lst)):
        if lst[i] < prev:
            return False
        if lst[i] == prev:
            duplicates += 1
            if duplicates > 1:
                return False
        else:
            duplicates = 0
        prev = lst[i]

    return True
