def sort_array(array):
    import copy

    def sort_ascending(arr):
        return sorted(arr)

    def sort_descending(arr):
        return sorted(arr, reverse=True)

    if len(array) == 0:
        return array

    first_last_sum = array[0] + array[-1]
    sorted_array = copy.copy(array)

    if first_last_sum % 2 == 0:
        sorted_array = sort_descending(array)
    else:
        sorted_array = sort_ascending(array)

    return sorted_array
