def valid_date(date):
    import re
    date_format = re.compile(r"^(0[1-9]|1[0-2])-([0-2][0-9]|3[01])-([0-9]{4})$")
    match = date_format.match(date)
    if not match:
        return False

    month, day, year = map(int, match.groups())
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if month in [4, 6, 9, 11] and day > 30:
        return False
    if month == 2:
        if day > 29:
            return False
        if day == 29 and not (year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)):
            return False

    return True
