def find_max(words: List[str]) -> str:
    def unique_chars(word: str) -> int:
        return len(set(word))

    max_word = ""
    max_unique = 0

    for word in words:
        current_unique = unique_chars(word)
        if current_unique > max_unique or (current_unique == max_unique and word < max_word):
            max_unique = current_unique
            max_word = word

    return max_word
