def is_sorted(lst):
    if len(lst) <= 1:
        return True
    last_num = lst[0]
    duplicates = False
    for i in range(1, len(lst)):
        if lst[i] < last_num:
            return False
        if lst[i] == last_num:
            duplicates = True
        if duplicates and lst[i] > last_num:
            return False
        last_num = lst[i]
    return True
```

