def check_dict_case(dictionary):
    if not dictionary:
        return False

    lower_keys = set(k for k in dictionary if isinstance(k, str) and k.islower())
    upper_keys = set(k for k in dictionary if isinstance(k, str) and k.isupper())

    # Check if all keys are either lower or upper case
    if len(lower_keys) + len(upper_keys) == len(dictionary) and len(lower_keys.intersection(upper_keys)) == 0:
        return True
    else:
        return False
