def skjkasdkd(lst):
    from math import isqrt

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i <= isqrt(n):
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sum_of_digits(n):
        return sum(int(digit) for digit in str(n))

    max_prime = max((num for num in lst if is_prime(num)), default=0)
    return sum_of_digits(max_prime)
