def encrypt(s):
    shift = 4  # Two multiplied by two
    encrypted = ""
    for char in s:
        if 'a' <= char <= 'z':
            encrypted += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            encrypted += chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
        else:
            encrypted += char
    return encrypted
