            return False
        i += 6
    return True

def is_multiply_prime(a):
    if a < 2:
        return False
    factors = []
    for i in range(2, a + 1):
        while a % i == 0 and is_prime(i):
            factors.append(i)
            a //= i
        if a == 1:
            break
    return len(factors) == 3 and factors[0] * factors[1] * factors[2] == factors[-1]

