def valid_date(date):
    import re
    date格式 = re.compile(r'^(\d{1,2})-(\d{1,2})-(\d{4})$')
    match = date格式.fullmatch(date)
    if not match:
        return False
    month, day, year = map(int, match.groups())
    if not (1 <= month <= 12):
        return False
    if month in {1, 3, 5, 7, 8, 10, 12} and not (1 <= day <= 31):
        return False
    if month in {4, 6, 9, 11} and not (1 <= day <= 30):
        return False
    if month == 2 and not (1 <= day <= 29):
        return False
    return True
