def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    start = planets.index(planet1) if planet1 in planets else -1
    end = planets.index(planet2) if planet2 in planets else -1

    if start == -1 or end == -1:
        return ()

    if start > end:
        start, end = end, start

    return tuple(planets[start+1:end])
```

